describe('Responsive Font Size on Small Screens', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.viewport('iphone-x');
  });

  it('should display readable font sizes on small screens without zooming', () => {
    cy.get('body').should('be.visible');

    cy.get('h1').each(($heading) => {
      cy.wrap($heading).should('have.css', 'font-size').and('not.equal', '0px');
      cy.wrap($heading).invoke('css', 'font-size').then((fontSize) => {
        const fontSizeValue = parseFloat(fontSize);
        expect(fontSizeValue).to.be.at.least(16);
      });
    });

    cy.get('p').each(($paragraph) => {
      cy.wrap($paragraph).should('have.css', 'font-size').and('not.equal', '0px');
      cy.wrap($paragraph).invoke('css', 'font-size').then((fontSize) => {
        const fontSizeValue = parseFloat(fontSize);
        expect(fontSizeValue).to.be.at.least(14);
      });
    });

    cy.get('button').each(($button) => {
      cy.wrap($button).should('have.css', 'font-size').and('not.equal', '0px');
      cy.wrap($button).invoke('css', 'font-size').then((fontSize) => {
        const fontSizeValue = parseFloat(fontSize);
        expect(fontSizeValue).to.be.at.least(14);
      });
    });

    cy.get('a').each(($link) => {
      cy.wrap($link).should('have.css', 'font-size').and('not.equal', '0px');
      cy.wrap($link).invoke('css', 'font-size').then((fontSize) => {
        const fontSizeValue = parseFloat(fontSize);
        expect(fontSizeValue).to.be.at.least(14);
      });
    });
  });

  it('should maintain readable font sizes across multiple small screen sizes', () => {
    const smallViewports = ['iphone-se2', 'iphone-12', 'iphone-x'];

    smallViewports.forEach((viewport) => {
      cy.viewport(viewport);
      cy.reload();

      cy.get('h1').first().invoke('css', 'font-size').then((fontSize) => {
        const fontSizeValue = parseFloat(fontSize);
        expect(fontSizeValue).to.be.at.least(16);
      });

      cy.get('p').first().invoke('css', 'font-size').then((fontSize) => {
        const fontSizeValue = parseFloat(fontSize);
        expect(fontSizeValue).to.be.at.least(14);
      });

      cy.get('body').should('not.have.css', 'zoom', '1.5');
      cy.get('body').should('not.have.css', 'zoom', '2');
    });
  });

  it('should not require horizontal scrolling due to font size on small screens', () => {
    cy.get('body').then(($body) => {
      const bodyWidth = $body.width();
      cy.get('*').each(($element) => {
        const elementWidth = $element.width();
        expect(elementWidth).to.be.lte(bodyWidth);
      });
    });

    cy.window().then((win) => {
      expect(win.innerWidth).to.equal(win.document.documentElement.clientWidth);
    });
  });
});
